#!/usr/bin/env node

import fs from 'node:fs'
import path from 'node:path'
import { spawnSync } from 'node:child_process'
import {
  bundleDirForInput,
  buildPublicationFiles,
  readBundleFiles,
} from './phr-core.mjs'

function usage(message) {
  if (message) console.error(message)
  console.error('Usage: node scripts/publish-bundle.mjs --input <publication-input.json>')
  process.exit(1)
}

function parseArgs(argv) {
  const args = { inputPath: null }
  for (let index = 2; index < argv.length; index += 1) {
    const arg = argv[index]
    if (arg === '--input') {
      args.inputPath = argv[index + 1] ?? null
      index += 1
      continue
    }
    usage(`Unknown argument: ${arg}`)
  }
  if (!args.inputPath) usage('Missing --input argument.')
  return args
}

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'))
}

function writeText(filePath, content) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true })
  fs.writeFileSync(filePath, content, 'utf8')
}

function git(repoRoot, args) {
  const result = spawnSync('git', args, { cwd: repoRoot, encoding: 'utf8' })
  if (result.status !== 0) {
    const output = [result.stdout, result.stderr].filter(Boolean).join('\n').trim()
    throw new Error(output || `git ${args.join(' ')} failed with exit code ${result.status}`)
  }
  return result.stdout.trim()
}

function gitResult(repoRoot, args) {
  const result = spawnSync('git', args, { cwd: repoRoot, encoding: 'utf8' })
  return {
    ok: result.status === 0,
    output: [result.stdout, result.stderr].filter(Boolean).join('\n').trim(),
  }
}

function prepareCanonicalMain(repoRoot) {
  const branch = git(repoRoot, ['branch', '--show-current'])
  if (branch !== 'main') {
    throw new Error(`PHR publication requires branch main; current branch is ${branch || '<detached>'}`)
  }
  const dirty = git(repoRoot, ['status', '--porcelain'])
  if (dirty !== '') {
    throw new Error('PHR publication requires a clean checkout before bundle materialization.')
  }
  git(repoRoot, ['fetch', 'origin', 'main'])
  git(repoRoot, ['merge', '--ff-only', 'origin/main'])
}

function pushWithOptimisticRetry(repoRoot, maxAttempts = 3) {
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    const push = gitResult(repoRoot, ['push', 'origin', 'HEAD:main'])
    if (push.ok) return attempt
    if (!/non-fast-forward|fetch first|rejected/i.test(push.output)) {
      throw new Error(push.output || 'PHR publication push failed.')
    }
    if (attempt === maxAttempts) {
      throw new Error(`[RETRYABLE] PHR publication lost a concurrent push race after ${maxAttempts} attempts: ${push.output}`)
    }
    git(repoRoot, ['fetch', 'origin', 'main'])
    git(repoRoot, ['rebase', 'origin/main'])
  }
  throw new Error('[RETRYABLE] PHR publication retry loop terminated unexpectedly.')
}

function verifyPublishedCommit(repoRoot, commitSha) {
  git(repoRoot, ['fetch', 'origin', 'main'])
  const reachability = gitResult(repoRoot, ['merge-base', '--is-ancestor', commitSha, 'origin/main'])
  if (!reachability.ok) {
    throw new Error(`[RETRYABLE] Publication commit ${commitSha} is not reachable from origin/main.`)
  }
}

function main() {
  const { inputPath } = parseArgs(process.argv)
  const repoRoot = process.cwd()
  const input = readJson(path.resolve(inputPath))
  prepareCanonicalMain(repoRoot)

  const bundleDir = bundleDirForInput(repoRoot, input)
  const manifestPath = path.join(bundleDir, 'manifest.json')
  const existingFiles = readBundleFiles(bundleDir)
  const { files: expectedFiles, manifest: expectedManifest } = buildPublicationFiles(input, existingFiles)

  const expectedNames = new Set(expectedFiles.keys())
  for (const existingName of existingFiles.keys()) {
    if (!expectedNames.has(existingName)) {
      throw new Error(`Existing bundle contains unexpected file: ${existingName}`)
    }
  }

  for (const [fileName, expectedContent] of expectedFiles.entries()) {
    const existingContent = existingFiles.get(fileName)
    if (existingContent !== undefined && existingContent !== expectedContent) {
      throw new Error(`Bundle conflict detected for ${fileName}`)
    }
  }

  const bundleAlreadyTracked = fs.existsSync(bundleDir) && git(repoRoot, ['status', '--porcelain', '--', path.relative(repoRoot, bundleDir)]) === ''

  if (!fs.existsSync(bundleDir)) {
    fs.mkdirSync(bundleDir, { recursive: true })
  }

  for (const [fileName, content] of expectedFiles.entries()) {
    writeText(path.join(bundleDir, fileName), content)
  }

  const bundleRelativePath = path.relative(repoRoot, bundleDir)
  const gitStatus = git(repoRoot, ['status', '--porcelain', '--', bundleRelativePath])
  let pushAttempts = 0
  if (gitStatus !== '') {
    git(repoRoot, ['add', bundleRelativePath])
    git(repoRoot, ['commit', '-m', `Publish ${input.publicationId}`])
    pushAttempts = pushWithOptimisticRetry(repoRoot)
  }

  const commitSha = git(repoRoot, ['rev-parse', 'HEAD'])
  verifyPublishedCommit(repoRoot, commitSha)
  const payload = {
    status: bundleAlreadyTracked || gitStatus === '' ? 'IDEMPOTENT' : 'PUBLISHED',
    bundlePath: bundleRelativePath,
    manifestPath: path.relative(repoRoot, manifestPath),
    commitSha,
    publicationId: input.publicationId,
    taskId: input.taskId,
    artifactCount: input.artifacts.length,
    integrityEnabled: expectedManifest.artifacts.some((artifact) => artifact.type === 'integrity.json'),
    pushAttempts,
  }

  process.stdout.write(`${JSON.stringify(payload, null, 2)}\n`)
}

try {
  main()
} catch (error) {
  const message = (error && error.message) ? error.message : String(error)
  const status = error && error.status === 'CONFLICT'
    ? 'CONFLICT'
    : typeof message === 'string' && message.includes('Bundle conflict detected')
      ? 'CONFLICT'
      : typeof message === 'string' && message.includes('[RETRYABLE]')
        ? 'FAILED_RETRYABLE'
        : 'FAILED'
  process.stdout.write(`${JSON.stringify({ status, message }, null, 2)}\n`)
  console.error(message)
  process.exit(1)
}

