#!/usr/bin/env node

import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'

export const EXPECTED_SOURCE_SYSTEM = 'PMOS'
export const EXPECTED_SCHEMA_VERSION = '1.0'
export const INTEGRITY_SCHEMA_VERSION = '1.0'

const SECRET_FIELD = '(?:api[_-]?key|access[_-]?token|auth[_-]?token|private[_ -]?key|token|password|secret)'
const SECRET_ASSIGNMENT_PATTERNS = [
  // A narrative sentence may mention "secret:" without assigning a credential.
  // Keep fail-closed detection for configuration lines, object properties and
  // inline environment-style assignments instead of matching any word in prose.
  new RegExp(`(?:^|\\r?\\n|["'])[ \\t]*(?:export[ \\t]+)?["']?${SECRET_FIELD}["']?[ \\t]*[:=][ \\t]*\\S+`, 'im'),
  new RegExp(`(?:^|[,{])[ \\t]*["']${SECRET_FIELD}["'][ \\t]*:[ \\t]*\\S+`, 'i'),
  new RegExp(`\\b${SECRET_FIELD}[ \\t]*=[ \\t]*\\S+`, 'i'),
]

const SECRET_PATTERNS = [
  // A format name alone is prose. Keep key assignments (including inline
  // colon notation) and key envelopes blocked regardless of nearby narrative.
  /\bprivate[_ -]?key\b(?:\\*["'])?[ \t]*[:=][ \t]*\S+/i,
  /\b(?:BEGIN|END) (?:[A-Z0-9]+ )*PRIVATE KEY\b/i,
  /postgres(?:ql)?:\/\//i,
  /mysql:\/\//i,
  /mongodb:\/\//i,
  // "Bearer tokens" names a format in prose, but real Authorization headers
  // and all other standalone Bearer values (including short ones) still match.
  // Keep quoted/JSON-escaped and Markdown-formatted headers blocked even when
  // their value contains an otherwise permitted narrative phrase.
  /\bAuthorization(?:\\*["']|[*_\x60])*\s*[:=]\s*(?:\\*["']|[*_\x60])*\s*Bearer\s+\S+/i,
  // Only the exact Polish or English narrative context is exempt here.
  // Header assignments still scan untouched text, including short values.
  // "peer read" is an exact phrase, never a token prefix. The hyphenated form
  // is prose only in the exact Polish table wording; bare Bearer peer-read
  // remains a credential. Header/secret assignments above are never exempt.
  /(?<!token typu )(?<!untrusted user )Bearer\s+(?!tokens?\b|peer read(?![A-Za-z0-9._~+\/=-])|(?<=\bbrak rozszerzenia Bearer )peer-read(?= \|))[A-Za-z0-9._-]+|(?<=untrusted user )Bearer\s+(?!session to the actual current backend guard\b|tokens?\b)[A-Za-z0-9._-]+|(?<=token typu )Bearer\s+(?!jest\s+weryfikowany\b|tokens?\b)[A-Za-z0-9._-]+/i,
]

function sha256(text) {
  return crypto.createHash('sha256').update(text, 'utf8').digest('hex')
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
}

// Complete descriptive clauses name session behaviour, not a scheme/value.
// This scan-only view never changes publication bytes. Assignments, URLs and
// key envelopes are always checked against the untouched text first.
const SESSION_NARRATIVES = [
  /\bexisting SDK bearer with at least30seconds headroom\./gi,
  /\bcached Clerk bearer expired during the first\d+second report request;/gi,
  /\bat the exact bearer expiry,\d{2}:\d{2}:\d{2}Z\./gi,
  /\bfix the cached bearer at the client start instead of weakening expiry checks\./gi,
  /\bpreserving PILOT2 admitted bearer and final E1 checks\./gi,
  /\bfresh-session bearer correction PR[1-9][0-9]* is separately under required CI after one request expired during[1-9][0-9]*-second execution;/gi,
]
function standaloneCredentialView(text) {
  return SESSION_NARRATIVES.reduce((view, phrase) => view.replace(phrase, matched => matched.replace(/\bbearer\b/gi, 'credential')), text)
}

export function secretScanText(text) {
  // Scan the untouched text first. An additional view exposes quoted
  // assignments and line boundaries inside JSON strings; never rewrite content.
  const views = [text, text.replace(/\\+(["'nr])/g, (_, value) => value === 'n' ? '\n' : value === 'r' ? '\r' : value)]
  return views.some((view) => SECRET_ASSIGNMENT_PATTERNS.some((pattern) => pattern.test(view))
    || SECRET_PATTERNS.slice(0, -1).some((pattern) => pattern.test(view))
    || SECRET_PATTERNS.at(-1).test(standaloneCredentialView(view)))
}

export function secretScanValue(value) {
  return secretScanText(JSON.stringify(value))
}

export function normalizeTimestamp(timestamp) {
  const match = /^([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})\.[0-9]{3}Z$/.exec(timestamp)
  if (!match) {
    throw new Error(`Invalid ISO timestamp: ${timestamp}`)
  }
  return `${match[1]}-${match[2]}-${match[3]}-${match[4]}-${match[5]}-${match[6]}Z`
}

export function slugify(value) {
  return String(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

export function bundleDirForInput(repoRoot, input) {
  const date = input.publishedAt.slice(0, 10)
  const timestamp = normalizeTimestamp(input.publishedAt)
  return path.join(repoRoot, 'history', date.slice(0, 4), date.slice(5, 7), date.slice(8, 10), `${timestamp}__${slugify(input.publicationId)}`)
}

export function renderHandoffMarkdown(handoff) {
  const payload = handoff.payload ?? {}
  const list = (items, emptyLabel) => Array.isArray(items) && items.length > 0
    ? items.map((item) => `- ${item}`).join('\n')
    : emptyLabel

  return [
    '# GPT HANDOFF',
    '',
    `Artifact ID: ${handoff.id}`,
    'Persistence: POSTGRESQL',
    `Status: ${handoff.status}`,
    'Source: Closeout',
    `Conversation ID: ${handoff.conversationId}`,
    `Task ID: ${handoff.taskId}`,
    `Artifact Nature: ${handoff.artifactNature}`,
    `Artifact Kind: ${handoff.artifactKind}`,
    `Created At: ${handoff.createdAt}`,
    'Lineage:',
    'Conversation',
    '→ Flight Record',
    '→ Closeout',
    '→ HANDOFF',
    '',
    '## HANDOFF SUMMARY',
    '',
    '### Original Objective',
    '',
    payload.originalObjective ?? '',
    '',
    '### CURRENT STATE',
    '',
    list(payload.currentState, '_None recorded._'),
    '',
    '### Completed Work',
    '',
    list(payload.completedWork, '_None recorded._'),
    '',
    '### Not Completed',
    '',
    list(payload.notCompleted, '_None recorded._'),
    '',
    '### Key Findings',
    '',
    list(payload.keyFindings, '_None recorded._'),
    '',
    '### Decisions',
    '',
    list(payload.decisions, '_None recorded._'),
    '',
    '### Blockers',
    '',
    list(payload.blockers, '_None recorded._'),
    '',
    '### Residual Risks',
    '',
    list(payload.residualRisks, '_None recorded._'),
    '',
    '### Open Questions',
    '',
    list(payload.openQuestions, '_None recorded._'),
    '',
    '### Outstanding Topics',
    '',
    list(payload.outstandingTopics, '_None recorded._'),
    '',
    '## GPT BRIDGE PAYLOAD',
    '',
    payload.bridgePayloadText ?? '',
    '',
  ].join('\n')
}

export function normalizeArtifactDescriptor(artifact) {
  return {
    type: artifact.type,
    status: artifact.status,
    path: artifact.path,
    sourceId: artifact.sourceId ?? null,
  }
}

export function validateInput(input) {
  if (!isPlainObject(input)) {
    throw new Error('Publication input must be a JSON object.')
  }

  const required = ['schemaVersion', 'publicationId', 'taskId', 'projectId', 'createdAt', 'publishedAt', 'result', 'closeoutState', 'sourceSystem', 'artifacts']
  for (const key of required) {
    if (!(key in input)) throw new Error(`Publication input is missing required field: ${key}`)
  }

  if (input.schemaVersion !== EXPECTED_SCHEMA_VERSION) {
    throw new Error(`Unsupported schemaVersion: ${input.schemaVersion}`)
  }

  if (input.sourceSystem !== EXPECTED_SOURCE_SYSTEM) {
    throw new Error(`Unsupported sourceSystem: ${input.sourceSystem}`)
  }

  if (!Array.isArray(input.artifacts) || input.artifacts.length === 0) {
    throw new Error('Publication input must include at least one artifact.')
  }

  for (const artifact of input.artifacts) {
    if (!isPlainObject(artifact)) {
      throw new Error('Each artifact entry must be an object.')
    }
    if (!artifact.type || !artifact.status) {
      throw new Error('Each artifact entry must include type and status.')
    }
    if (!['PRESENT', 'ABSENT'].includes(artifact.status)) {
      throw new Error(`Unsupported artifact status: ${artifact.status}`)
    }
    if (artifact.status === 'PRESENT' && !artifact.path) {
      throw new Error(`Artifact ${artifact.type} is PRESENT but missing path.`)
    }
  }
}

function artifactContentToText(artifact) {
  if (artifact.path.endsWith('.md')) {
    const content = typeof artifact.content === 'string' ? artifact.content : renderHandoffMarkdown(artifact.content)
    return content.endsWith('\n') ? content : `${content}\n`
  }
  return `${JSON.stringify(artifact.content, null, 2)}\n`
}

export function readBundleFiles(bundleDir) {
  const entries = fs.existsSync(bundleDir) ? fs.readdirSync(bundleDir, { withFileTypes: true }) : []
  const files = new Map()
  for (const entry of entries) {
    if (entry.isFile()) {
      files.set(entry.name, fs.readFileSync(path.join(bundleDir, entry.name), 'utf8'))
    }
  }
  return files
}

function hashFiles(files) {
  const entries = [...files.entries()].sort(([left], [right]) => left.localeCompare(right))
  const payload = entries.map(([filePath, content]) => `${filePath}\u0000${sha256(content)}`).join('\u0000')
  return sha256(payload)
}

export function buildIntegrityFile(files) {
  const fileHashes = [...files.entries()]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([filePath, content]) => ({ path: filePath, sha256: sha256(content) }))
  const bundleHash = hashFiles(files)
  const integrity = {
    schemaVersion: INTEGRITY_SCHEMA_VERSION,
    algorithm: 'sha256',
    bundleHash,
    files: fileHashes,
  }
  return `${JSON.stringify(integrity, null, 2)}\n`
}

export function buildPublicationFiles(input, existingFiles = new Map()) {
  validateInput(input)

  const files = new Map()
  let containsSecret = secretScanValue(input)

  for (const artifact of input.artifacts) {
    if (artifact.status !== 'PRESENT') continue
    if (!artifact.path) throw new Error(`Artifact ${artifact.type} is PRESENT but missing path.`)
    if (artifact.content === undefined || artifact.content === null) {
      throw new Error(`Artifact ${artifact.type} is PRESENT but missing content.`)
    }

    const content = artifactContentToText(artifact)
    files.set(artifact.path, content)
    containsSecret = containsSecret || secretScanText(content)
  }

  if (containsSecret) {
    const error = new Error('Secret scan hit')
    error.status = 'FAILED'
    throw error
  }

  const useIntegrity = existingFiles.size === 0 || existingFiles.has('integrity.json')
  const manifestArtifacts = input.artifacts.map(normalizeArtifactDescriptor)

  if (useIntegrity) {
    manifestArtifacts.push({
      type: 'integrity.json',
      status: 'PRESENT',
      path: 'integrity.json',
      sourceId: null,
    })
  }

  const manifest = {
    schemaVersion: input.schemaVersion,
    publicationId: input.publicationId,
    taskId: input.taskId,
    projectId: input.projectId,
    createdAt: input.createdAt,
    publishedAt: input.publishedAt,
    result: input.result,
    closeoutState: input.closeoutState,
    sourceSystem: input.sourceSystem,
    artifacts: manifestArtifacts,
  }

  files.set('manifest.json', `${JSON.stringify(manifest, null, 2)}\n`)
  if (useIntegrity) {
    const integrityContent = buildIntegrityFile(files)
    files.set('integrity.json', integrityContent)
  }
  return {
    files,
    manifest,
    integrityEnabled: useIntegrity,
    bundleFingerprint: hashFiles(files),
  }
}

export function validateManifest(manifest) {
  if (!isPlainObject(manifest)) {
    throw new Error('Manifest must be a JSON object.')
  }

  const required = ['schemaVersion', 'publicationId', 'taskId', 'projectId', 'createdAt', 'publishedAt', 'result', 'closeoutState', 'sourceSystem', 'artifacts']
  for (const key of required) {
    if (!(key in manifest)) throw new Error(`Manifest is missing required field: ${key}`)
  }

  if (manifest.schemaVersion !== EXPECTED_SCHEMA_VERSION) {
    throw new Error(`Unsupported schemaVersion: ${manifest.schemaVersion}`)
  }

  if (manifest.sourceSystem !== EXPECTED_SOURCE_SYSTEM) {
    throw new Error(`Unsupported sourceSystem: ${manifest.sourceSystem}`)
  }

  if (!Array.isArray(manifest.artifacts) || manifest.artifacts.length === 0) {
    throw new Error('Manifest must include at least one artifact.')
  }

  return true
}

export function expectedBundleFileNames(manifest) {
  const names = new Set(['manifest.json'])
  for (const artifact of manifest.artifacts) {
    if (artifact.status === 'PRESENT' && artifact.path) {
      names.add(artifact.path)
    }
  }
  return names
}

export function validateBundleDirectory(bundleDir) {
  const issues = []
  const manifestPath = path.join(bundleDir, 'manifest.json')

  if (!fs.existsSync(manifestPath)) {
    issues.push('Missing manifest.json')
    return { issues }
  }

  let manifest
  try {
    manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'))
    validateManifest(manifest)
  } catch (error) {
    issues.push(error instanceof Error ? error.message : String(error))
    return { issues }
  }

  const actualFiles = readBundleFiles(bundleDir)
  const expectedNames = expectedBundleFileNames(manifest)

  for (const fileName of expectedNames) {
    if (!actualFiles.has(fileName)) {
      issues.push(`Missing file referenced by manifest: ${fileName}`)
    }
  }

  for (const fileName of actualFiles.keys()) {
    if (!expectedNames.has(fileName)) {
      issues.push(`Unexpected file in bundle: ${fileName}`)
    }
  }

  if (actualFiles.has('integrity.json')) {
    try {
      const integrity = JSON.parse(actualFiles.get('integrity.json'))
      if (integrity.schemaVersion !== INTEGRITY_SCHEMA_VERSION) {
        throw new Error(`Unsupported integrity schemaVersion: ${integrity.schemaVersion}`)
      }
      if (integrity.algorithm !== 'sha256') {
        throw new Error(`Unsupported integrity algorithm: ${integrity.algorithm}`)
      }

      const filesForHash = new Map([...actualFiles.entries()].filter(([fileName]) => fileName !== 'integrity.json'))
      const expectedHashes = [...filesForHash.entries()]
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([filePath, content]) => ({ path: filePath, sha256: sha256(content) }))
      const expectedBundleHash = hashFiles(filesForHash)
      if (integrity.bundleHash !== expectedBundleHash) {
        throw new Error('Integrity bundle hash mismatch')
      }
      const expectedHashIndex = new Map(expectedHashes.map((entry) => [entry.path, entry.sha256]))
      if (!Array.isArray(integrity.files)) {
        throw new Error('Integrity files payload is malformed')
      }
      if (integrity.files.length !== expectedHashes.length) {
        throw new Error('Integrity file count mismatch')
      }
      for (const entry of integrity.files) {
        if (!entry || typeof entry.path !== 'string' || typeof entry.sha256 !== 'string') {
          throw new Error('Integrity entry is malformed')
        }
        if (expectedHashIndex.get(entry.path) !== entry.sha256) {
          throw new Error(`Integrity hash mismatch for ${entry.path}`)
        }
      }
    } catch (error) {
      issues.push(error instanceof Error ? error.message : String(error))
    }
  }

  return { issues, manifest, actualFiles }
}

export function checkRepository(repoRoot) {
  const historyRoot = path.join(repoRoot, 'history')
  const manifestPaths = []

  function walk(dir) {
    if (!fs.existsSync(dir)) return
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const entryPath = path.join(dir, entry.name)
      if (entry.isDirectory()) {
        walk(entryPath)
      } else if (entry.isFile() && entry.name === 'manifest.json') {
        manifestPaths.push(entryPath)
      }
    }
  }

  walk(historyRoot)

  const issues = []
  const publicationIds = new Map()
  const bundlePaths = new Set()

  for (const manifestPath of manifestPaths.sort()) {
    const bundleDir = path.dirname(manifestPath)
    const bundleRelativePath = path.relative(repoRoot, bundleDir)
    if (bundlePaths.has(bundleRelativePath)) {
      issues.push(`Duplicate bundle path: ${bundleRelativePath}`)
    }
    bundlePaths.add(bundleRelativePath)

    const result = validateBundleDirectory(bundleDir)
    issues.push(...result.issues.map((issue) => `${bundleRelativePath}: ${issue}`))

    if (result.manifest?.publicationId) {
      const seenPath = publicationIds.get(result.manifest.publicationId)
      if (seenPath && seenPath !== bundleRelativePath) {
        issues.push(`Duplicate publicationId ${result.manifest.publicationId} in ${seenPath} and ${bundleRelativePath}`)
      } else {
        publicationIds.set(result.manifest.publicationId, bundleRelativePath)
      }
    }
  }

  return {
    repositoryRoot: repoRoot,
    bundleCount: manifestPaths.length,
    issues,
  }
}
